The quiver Hecke algebra $H_{n}(\Gamma)$ associated to $\Gamma$ is a (possibly non-unitary) $k$-algebra with generators $\{1_{\alpha}\}_{\alpha\in K^{n}}$, $\{x_{a}\}_{1\leq a\leq n}$ and $\{\tau_{i}\}_{1\leq i\leq n-1}$ and relations:

\begin{align}
1_{\alpha}1_{\alpha'}&=\delta_{\alpha,\alpha'}1_{\alpha},\qquad\sum_{\alpha\in K^{n}}1_{\alpha}=1; \\[0.2em]
\tau_{i}1_{\alpha}&=1_{s_{i}(\alpha)}\tau_{i},\qquad x_{a}1_{\alpha}=1_{\alpha}x_{a}; \\[0.2em]
x_{a}x_{b}&=x_{b}x_{a},\qquad \quad \tau_{i}\tau_{j}=\tau_{j}\tau_{i} \quad \mbox{if $\vert i-j\vert \geq 2$;} \\[0.2em]
\tau_{i}x_{a}1_{\alpha}-x_{s_{i}(a)}\tau_{i}1_{\alpha}&=\left\{
\begin{array}{ll}
-1_{\alpha}&\text{if $a=i$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
1_{\alpha}&\text{if $a=i+1$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
0&\text{otherwise;}
\end{array}
\right. \\[0.2em]
\tau_{i}^{2}1_{\alpha}&=Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1})1_{\alpha}; \\[0.2em]
\nonumber\tau_{i+1}\tau_{i}\tau_{i+1}1_{\alpha}-\tau_{i}\tau_{i+1}\tau_{i}1_{\alpha}&=\end{align}
\begin{align}
\left\{
\begin{array}{ll}
(x_{i+2}-x_{i})^{-1}(Q_{\alpha_i, \alpha_{i+1}}(x_{i+2}, x_{i+1})-Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1}))1_{\alpha}&\text{if $\alpha_i = \alpha_{i+2}$},\\[0.3em]
0&\text{otherwise,}
\end{array}
\right. \end{align}
for $\alpha,\alpha'\in K^{n},$ $1\leq a,b\leq n$ and $1\leq i,j\leq n-1,$ and where\\
\[Q_{\alpha_i, \alpha_{i+1}}(u, v)=\left\{
\begin{array}{ll}
0&\text{if $\alpha_i = \alpha_{i+1}$},\\[0.05em]
1&\text{if $\alpha_i\:\notslash\: \alpha_{i+1}$},\\[0.05em]
v-u&\text{if $\alpha_i\rightarrow \alpha_{i+1}$},\\[0.05em]
u-v&\text{if $\alpha_i\leftarrow \alpha_{i+1}$},\\[0.05em]
-(u-v)^{2}&\text{if $\alpha_i\rightleftarrows \alpha_{i+1}$}.
\end{array}
\right.\]

\tau_{i}x_{a}1_{\alpha}-x_{s_{i}(a)}\tau_{i}1_{\alpha}&=\left\{
\begin{array}{ll}
-1_{\alpha}&\text{if $a=i$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
1_{\alpha}&\text{if $a=i+1$ and $\alpha_i = \alpha_{i+1}$},\\[0.2em]
0&\text{otherwise;}
\end{array}
\right.

\left\{
\begin{array}{ll}
(x_{i+2}-x_{i})^{-1}(Q_{\alpha_i, \alpha_{i+1}}(x_{i+2}, x_{i+1})-Q_{\alpha_i, \alpha_{i+1}}(x_{i}, x_{i+1}))1_{\alpha}&\text{if $\alpha_i = \alpha_{i+2}$},\\[0.3em]
0&\text{otherwise,}
\end{array}
\right.

\begin{align}
f\tau_{i}1_{(\nu, j)}=\left\{
