\vspace{0.15cm}
for any $1\leq i\leq n-1,$ $(\nu, j)\in K^{n}$ and $f\in k[[x_1,\dots,x_n]]$, and where
\begin{equation*}
\partial_{i}(f):=\frac{f-{}^{s_{i}}f}{x_{i+1}-x_{i}}.
\end{equation*}

